SELECT p.*, CASE WHEN area_ha > 0 AND production_t IS NOT NULL THEN 1000.0 * production_t / NULLIF(area_ha,0) END AS computed_yield_kg_ha FROM (SELECT f.year_key, f.geography_key, f.product_key, MAX(CASE WHEN t.source_metric_id='5312' THEN f.value END) AS area_ha, count_if(t.source_metric_id='5312') AS present_5312, MAX(CASE WHEN t.source_metric_id='5312' THEN f.observation_key END) AS observation_5312, MAX(CASE WHEN t.source_metric_id='5510' THEN f.value END) AS production_t, count_if(t.source_metric_id='5510') AS present_5510, MAX(CASE WHEN t.source_metric_id='5510' THEN f.observation_key END) AS observation_5510, MAX(CASE WHEN t.source_metric_id='5412' THEN f.value END) AS reported_yield_kg_ha, count_if(t.source_metric_id='5412') AS present_5412, MAX(CASE WHEN t.source_metric_id='5412' THEN f.observation_key END) AS observation_5412 FROM {{fact_fao_production_observation}} f JOIN {{dim_observation_type}} t ON f.observation_type_key=t.observation_type_key GROUP BY f.year_key, f.geography_key, f.product_key) p
